//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::int::neg`; the
//! native twin is `benches/native/Bench/IntNeg.lean`.
//! Int words in the int32 range on both sides; every result stays there

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::int;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            int_unbox(int_res(int::neg(int_arg(int_box(
                ((x >> 34) as i64) - (1 << 29),
            ))))) as u64,
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
